/**
 * Crow Studio — the widget shell, as one inline classic script.
 *
 * The song page is a page of widgets now: a scene grid, one editor slot, the
 * takes lane, the MIDI lane, the history and the agent. This file builds that
 * page around the markup the panel already renders. It MOVES the nodes the
 * page already has (it never clones them), so the page's own script keeps
 * finding the same elements, keeps its delegated click handler and keeps every
 * render painting the nodes it drew. The only decisions it makes are the ones
 * `panel/shell-layout.js` owns: which widget is on the page, in what order and
 * at which size. This file reads that model and never re-implements it.
 *
 * Like `panel/client.js` and `panel/midi-route.js` it travels as a string
 * (`SHELL_SCRIPT`) and is written as an EXPRESSIONS ONLY classic script: no
 * backtick, no `${`, no double quote and no backslash anywhere in the emitted
 * text. It assigns one global — `window.StudioShell` — and the page mounts it
 * once, after the layout model and before the client.
 *
 * ## What it owns
 *
 * `window.StudioShell.mount(page, hooks)` builds one top bar, one screen
 * container (the timeline and the mixer), one widget area (the frames) and one
 * hidden tray inside `.studio` for the widgets this layout does not show. A
 * frame in the tray stays in the document, so `page.querySelector` still finds
 * its body and a reply written while it was hidden is there when it is shown.
 *
 * The hooks are the page's own reading of itself:
 * `{hosts, songId, storage, screen(), render(), onMode(mode)}`. `hosts` names
 * the nodes a widget wraps (one element or a list); a widget it does not name
 * is found by its `data-role`, and the agent host is created around the Ask
 * label and box when the page has no `[data-role=ask]` yet.
 *
 * The returned controller is `{refresh(), setMode(mode), destroy()}`.
 * `refresh` compares the layout it last applied with the current one and the
 * screen the page reports, and touches the DOM only when one of them moved, so
 * it is safe at the end of every render. `destroy` removes its listeners and
 * observers and puts every moved node back, which is what a Turbo teardown
 * needs. Mounting again adopts the frames that are already there, so a boot,
 * a teardown and another boot leave one set of frames.
 *
 * The CSS below is an array instead of a template literal so the CSS value
 * carries no backtick at all; it lands after the page's own style block.
 *
 * @type {string}
 */
export const SHELL_SCRIPT = [
  "(function () {",
  "  'use strict';",
  "",
  "  var MODE_KEY = 'crow.studio.mode.v1';",
  "  var MODES = ['compose', 'perform', 'record'];",
  "  var MODE_LABELS = { compose: 'Compose', perform: 'Perform', record: 'Record' };",
  "",
  "  // What a frame calls itself in its header, and the one sentence a frame",
  "  // shows when every host it wraps is hidden.",
  "  var WIDGET_NAMES = {",
  "    'scene-grid': 'Scene grid',",
  "    'editor': 'Editor',",
  "    'takes': 'Takes',",
  "    'midi': 'MIDI',",
  "    'history': 'History',",
  "    'agent': 'Agent'",
  "  };",
  "  var WIDGET_NOTES = {",
  "    'editor': 'Pick a clip in the grid to edit it.',",
  "    'takes': 'Arm a track to record.'",
  "  };",
  "",
  "  // Where a widget's hosts are when the caller did not hand them in.",
  "  var HOST_QUERIES = {",
  "    'scene-grid': ['[data-role=grid-wrap]', '[data-role=hint]'],",
  "    'editor': ['[data-role=editor]', '[data-role=sampler]'],",
  "    'takes': ['[data-role=recordings]'],",
  "    'midi': ['[data-role=midi]'],",
  "    'history': ['[data-role=history]']",
  "  };",
  "  var WIDGET_ORDER = ['scene-grid', 'editor', 'takes', 'midi', 'history', 'agent'];",
  "",
  "  function hasOwn(object, key) {",
  "    return Object.prototype.hasOwnProperty.call(object, key);",
  "  }",
  "",
  "  function el(tag, className, text) {",
  "    var node = document.createElement(tag);",
  "    if (className) node.className = className;",
  "    if (text !== undefined) node.textContent = text;",
  "    return node;",
  "  }",
  "",
  "  function button(className, text, attrs) {",
  "    var node = el('button', className, text);",
  "    node.setAttribute('type', 'button');",
  "    if (attrs) {",
  "      for (var name in attrs) {",
  "        if (hasOwn(attrs, name)) node.setAttribute(name, String(attrs[name]));",
  "      }",
  "    }",
  "    return node;",
  "  }",
  "",
  "  function isHidden(node) {",
  "    if (!node) return true;",
  "    if (node.hidden === true) return true;",
  "    return !!(node.getAttribute && node.getAttribute('hidden') !== null);",
  "  }",
  "",
  "  // Visibility is always written through here, so a refresh that changes",
  "  // nothing writes nothing: the attribute is the only thing that moves.",
  "  function setHidden(node, hidden) {",
  "    if (!node) return;",
  "    var want = hidden === true;",
  "    if (isHidden(node) === want) return;",
  "    if (want) node.setAttribute('hidden', '');",
  "    else node.removeAttribute('hidden');",
  "  }",
  "",
  "  function setAttr(node, name, value) {",
  "    if (!node || typeof node.getAttribute !== 'function') return;",
  "    if (node.getAttribute(name) === value) return;",
  "    node.setAttribute(name, value);",
  "  }",
  "",
  "  function setStyle(node, name, value) {",
  "    if (!node || !node.style || typeof node.style.setProperty !== 'function') return;",
  "    var now = '';",
  "    if (typeof node.style.getPropertyValue === 'function') now = node.style.getPropertyValue(name);",
  "    if (now === value) return;",
  "    node.style.setProperty(name, value);",
  "  }",
  "",
  "  function setText(node, text) {",
  "    if (!node) return;",
  "    if (node.textContent !== text) node.textContent = text;",
  "  }",
  "",
  "  // A brokered read and write: a store that throws, or was never handed in,",
  "  // answers the way a browser that refuses storage does.",
  "  function readValue(storage, key) {",
  "    if (!storage || typeof storage.getItem !== 'function') return null;",
  "    try {",
  "      var value = storage.getItem(key);",
  "      return value === undefined ? null : value;",
  "    } catch (err) {",
  "      return null;",
  "    }",
  "  }",
  "",
  "  function writeValue(storage, key, value) {",
  "    if (!storage || typeof storage.setItem !== 'function') return false;",
  "    try {",
  "      storage.setItem(key, value);",
  "      return true;",
  "    } catch (err) {",
  "      return false;",
  "    }",
  "  }",
  "",
  "  function storageOf(hooks) {",
  "    if (hooks && hooks.storage && typeof hooks.storage.getItem === 'function') return hooks.storage;",
  "    try {",
  "      if (window.localStorage && typeof window.localStorage.getItem === 'function') return window.localStorage;",
  "    } catch (err) {",
  "      return null;",
  "    }",
  "    return null;",
  "  }",
  "",
  "  // One element or a list of them, as a plain list of elements.",
  "  function listOf(value) {",
  "    var list = [];",
  "    if (!value) return list;",
  "    if (typeof value.length === 'number' && typeof value !== 'string' && !value.nodeType) {",
  "      for (var i = 0; i < value.length; i += 1) if (value[i]) list.push(value[i]);",
  "    } else if (value.nodeType) {",
  "      list.push(value);",
  "    }",
  "    return list;",
  "  }",
  "",
  "  window.StudioShell = {",
  "    mount: mount,",
  "    widgetName: function (id) { return WIDGET_NAMES[id] || ''; },",
  "    emptyNote: function (id) { return WIDGET_NOTES[id] || ''; }",
  "  };",
  "",
  "  /**",
  "   * Build the shell around the page's markup.",
  "   * @param {object} page - the studio element",
  "   * @param {object} hooks - the page's own reading of itself",
  "   * @returns {{refresh: Function, setMode: Function, destroy: Function}}",
  "   */",
  "  function mount(page, hooks) {",
  "    var control = { refresh: function () {}, setMode: function () {}, destroy: function () {} };",
  "    if (!page || typeof page.querySelector !== 'function') return control;",
  "    if (page.__studioShell) return page.__studioShell;",
  "    var layoutApi = window.StudioShellLayout;",
  "    if (!layoutApi || typeof layoutApi.loadLayout !== 'function') return control;",
  "    hooks = hooks || {};",
  "",
  "    var studio = page.classList && page.classList.contains('studio')",
  "      ? page : (page.querySelector('.studio') || page);",
  "    var storage = storageOf(hooks);",
  "    var moved = [];",
  "    var created = [];",
  "    var observers = [];",
  "    var listeners = [];",
  "    var media = [];",
  "    var closed = false;",
  "    var mediaMedium = null;",
  "    var mediaLarge = null;",
  "    var modeButtons = [];",
  "    var frames = {};",
  "    var state = { mode: 'compose', screen: null, shown: null, layoutText: '', unread: false, inRender: false };",
  "    var songId = hooks.songId === undefined || hooks.songId === null ? '' : String(hooks.songId);",
  "    if (songId === '') {",
  "      var songAttr = page.getAttribute && page.getAttribute('data-studio-song');",
  "      songId = songAttr ? String(songAttr) : '';",
  "    }",
  "",
  "    state.mode = readValue(storage, MODE_KEY);",
  "    if (MODES.indexOf(state.mode) < 0) state.mode = 'compose';",
  "",
  "    // ---- moving a node, with the way back --------------------------------",
  "",
  "    // A move remembers where the node came from, so destroy puts it back in",
  "    // the place the handler rendered it.",
  "    function moveTo(container, node, before) {",
  "      if (!container || !node) return;",
  "      if (node === before) return;",
  "      if (node.parentNode === container && node.nextSibling === before) return;",
  "      moved.push({ node: node, parent: node.parentNode, next: node.nextSibling });",
  "      if (before && before.parentNode === container) container.insertBefore(node, before);",
  "      else container.appendChild(node);",
  "    }",
  "",
  "    // Lay a container's nodes out in the given order, inserting only the",
  "    // nodes that are not already the next one.",
  "    function placeNodes(container, nodes) {",
  "      if (!container) return;",
  "      var cursor = container.firstChild;",
  "      for (var i = 0; i < nodes.length; i += 1) {",
  "        var node = nodes[i];",
  "        if (!node) continue;",
  "        if (node !== cursor) moveTo(container, node, cursor);",
  "        cursor = node.nextSibling;",
  "      }",
  "    }",
  "",
  "    // Every listener is recorded, so destroy removes exactly what mount added.",
  "    function listen(node, type, handler) {",
  "      if (!node) return;",
  "      listeners.push({ node: node, type: type, handler: handler });",
  "      node.addEventListener(type, handler);",
  "    }",
  "",
  "    // ---- the top bar ------------------------------------------------------",
  "",
  "    var top = page.querySelector('[data-role=studio-top]');",
  "    if (!top) {",
  "      top = el('div', 'st-top');",
  "      top.setAttribute('data-role', 'studio-top');",
  "      top.setAttribute('role', 'toolbar');",
  "      top.setAttribute('aria-label', 'Studio');",
  "      studio.insertBefore(top, studio.firstChild);",
  "      created.push(top);",
  "    }",
  "",
  "    var modeSwitch = top.querySelector('[data-role=mode-switch]');",
  "    if (!modeSwitch) {",
  "      modeSwitch = el('div', 'st-mode-switch');",
  "      modeSwitch.setAttribute('data-role', 'mode-switch');",
  "      modeSwitch.setAttribute('role', 'group');",
  "      modeSwitch.setAttribute('aria-label', 'Mode');",
  "      created.push(modeSwitch);",
  "    }",
  "    for (var m = 0; m < MODES.length; m += 1) {",
  "      var modeId = MODES[m];",
  "      var modeNode = modeSwitch.querySelector('[data-mode=' + modeId + ']');",
  "      if (!modeNode) {",
  "        modeNode = button('st-mode-switch-btn', MODE_LABELS[modeId], { 'data-mode': modeId });",
  "        modeSwitch.appendChild(modeNode);",
  "        created.push(modeNode);",
  "      }",
  "      setText(modeNode, MODE_LABELS[modeId]);",
  "      if (modeNode.getAttribute('aria-pressed') === null) modeNode.setAttribute('aria-pressed', 'false');",
  "      modeButtons.push({ mode: modeId, node: modeNode });",
  "      listen(modeNode, 'click', modeHandler(modeId));",
  "    }",
  "",
  "    // The Layout menu is a button and a popover. The entries and the MIDI",
  "    // block are empty containers the later panels fill by data-role.",
  "    var menu = top.querySelector('[data-role=layout-menu]');",
  "    var menuButton = null;",
  "    var popover = null;",
  "    var entries = null;",
  "    var midiEntries = null;",
  "    if (!menu) {",
  "      menu = el('div', 'st-layout-menu');",
  "      menu.setAttribute('data-role', 'layout-menu');",
  "      created.push(menu);",
  "    }",
  "    menuButton = menu.querySelector('[data-act=layout-menu]');",
  "    if (!menuButton) {",
  "      menuButton = button('st-btn st-small st-layout-btn', 'Layout', {",
  "        'data-act': 'layout-menu',",
  "        'aria-haspopup': 'true',",
  "        'aria-expanded': 'false'",
  "      });",
  "      menu.insertBefore(menuButton, menu.firstChild);",
  "      created.push(menuButton);",
  "    }",
  "    popover = menu.querySelector('[data-role=layout-popover]');",
  "    if (!popover) {",
  "      popover = el('div', 'st-layout-pop');",
  "      popover.setAttribute('data-role', 'layout-popover');",
  "      setHidden(popover, true);",
  "      menu.appendChild(popover);",
  "      created.push(popover);",
  "    }",
  "    entries = popover.querySelector('[data-role=layout-entries]');",
  "    if (!entries) {",
  "      entries = el('div', 'st-layout-entries');",
  "      entries.setAttribute('data-role', 'layout-entries');",
  "      popover.appendChild(entries);",
  "      created.push(entries);",
  "    }",
  "    midiEntries = popover.querySelector('[data-role=layout-midi]');",
  "    if (!midiEntries) {",
  "      midiEntries = el('div', 'st-layout-midi');",
  "      midiEntries.setAttribute('data-role', 'layout-midi');",
  "      popover.appendChild(midiEntries);",
  "      created.push(midiEntries);",
  "    }",
  "    listen(menuButton, 'click', toggleMenu);",
  "",
  "    var back = page.querySelector('.st-back');",
  "    var title = page.querySelector('[data-role=title]');",
  "    var modes = page.querySelector('.st-modes');",
  "    var presence = page.querySelector('[data-role=presence]');",
  "    placeNodes(top, [back, title, modeSwitch, modes, presence, menu]);",
  "",
  "    function modeHandler(modeId) {",
  "      return function () { setMode(modeId); };",
  "    }",
  "",
  "    function toggleMenu() {",
  "      var open = isHidden(popover);",
  "      setHidden(popover, !open);",
  "      setAttr(menuButton, 'aria-expanded', open ? 'true' : 'false');",
  "    }",
  "",
  "    // ---- the screen and the widget area ----------------------------------",
  "",
  "    var main = page.querySelector('.st-main') || studio;",
  "    var screenBox = page.querySelector('[data-role=studio-screen]');",
  "    if (!screenBox) {",
  "      screenBox = el('div', 'st-screen');",
  "      screenBox.setAttribute('data-role', 'studio-screen');",
  "      main.insertBefore(screenBox, main.firstChild);",
  "      created.push(screenBox);",
  "    }",
  "    var widgets = page.querySelector('[data-role=studio-widgets]');",
  "    if (!widgets) {",
  "      widgets = el('div', 'st-widgets');",
  "      widgets.setAttribute('data-role', 'studio-widgets');",
  "      if (screenBox.parentNode === main) {",
  "        if (screenBox.nextSibling) main.insertBefore(widgets, screenBox.nextSibling);",
  "        else main.appendChild(widgets);",
  "      } else {",
  "        main.appendChild(widgets);",
  "      }",
  "      created.push(widgets);",
  "    }",
  "    var tray = page.querySelector('[data-role=widget-tray]');",
  "    if (!tray) {",
  "      tray = el('div', 'st-widget-tray');",
  "      tray.setAttribute('data-role', 'widget-tray');",
  "      studio.appendChild(tray);",
  "      created.push(tray);",
  "    }",
  "    setHidden(tray, true);",
  "",
  "    moveTo(screenBox, page.querySelector('[data-role=timeline]'), null);",
  "    moveTo(screenBox, page.querySelector('[data-role=mixer]'), null);",
  "",
  "    // ---- the frames -------------------------------------------------------",
  "",
  "    function ensureFrame(id) {",
  "      var frame = page.querySelector('[data-widget=' + id + ']');",
  "      if (!frame) {",
  "        frame = el('section', 'st-widget');",
  "        frame.setAttribute('data-widget', id);",
  "        created.push(frame);",
  "      }",
  "      var head = frame.querySelector('.st-widget-head');",
  "      if (!head) {",
  "        head = el('div', 'st-widget-head');",
  "        frame.insertBefore(head, frame.firstChild);",
  "        created.push(head);",
  "      }",
  "      var name = head.querySelector('.st-widget-name');",
  "      if (!name) {",
  "        name = el('span', 'st-widget-name', WIDGET_NAMES[id] || id);",
  "        head.insertBefore(name, head.firstChild);",
  "        created.push(name);",
  "      } else {",
  "        setText(name, WIDGET_NAMES[id] || id);",
  "      }",
  "      var body = frame.querySelector('.st-widget-body');",
  "      if (!body) {",
  "        body = el('div', 'st-widget-body');",
  "        frame.appendChild(body);",
  "        created.push(body);",
  "      }",
  "      var noteText = WIDGET_NOTES[id] || '';",
  "      var note = body.querySelector('.st-widget-note');",
  "      if (noteText === '') {",
  "        if (note && note.parentNode) note.parentNode.removeChild(note);",
  "        note = null;",
  "      } else if (!note) {",
  "        note = el('p', 'st-widget-note', noteText);",
  "        body.appendChild(note);",
  "        created.push(note);",
  "      } else {",
  "        setText(note, noteText);",
  "      }",
  "      var dot = null;",
  "      if (id === 'agent') {",
  "        dot = head.querySelector('[data-role=unread]');",
  "        if (!dot) {",
  "          dot = el('span', 'st-widget-dot');",
  "          dot.setAttribute('data-role', 'unread');",
  "          setHidden(dot, true);",
  "          head.appendChild(dot);",
  "          created.push(dot);",
  "        }",
  "      }",
  "      var entry = { id: id, frame: frame, head: head, name: name, body: body, note: note, dot: dot, hosts: [] };",
  "      frames[id] = entry;",
  "      return entry;",
  "    }",
  "",
  "    var order = layoutApi.WIDGET_ORDER || WIDGET_ORDER;",
  "    for (var w = 0; w < order.length; w += 1) ensureFrame(order[w]);",
  "",
  "    function hostsFor(id) {",
  "      var given = hooks.hosts ? hooks.hosts[id] : null;",
  "      var list = listOf(given);",
  "      if (list.length > 0) return list;",
  "      var queries = HOST_QUERIES[id] || [];",
  "      for (var i = 0; i < queries.length; i += 1) {",
  "        var node = page.querySelector(queries[i]);",
  "        if (node) list.push(node);",
  "      }",
  "      if (list.length > 0) return list;",
  "      var fallback = page.querySelector('[data-role=' + id + ']');",
  "      if (fallback) list.push(fallback);",
  "      return list;",
  "    }",
  "",
  "    function attachHosts(entry, list) {",
  "      for (var i = 0; i < list.length; i += 1) {",
  "        if (!list[i]) continue;",
  "        moveTo(entry.body, list[i], null);",
  "        entry.hosts.push(list[i]);",
  "      }",
  "    }",
  "",
  "    // The agent host: the page has no [data-role=ask] yet, so the shell makes",
  "    // one whose DIRECT children are the existing Ask label and the .st-ask",
  "    // box. The client inserts its log beside .st-ask, which is why no inner",
  "    // wrapper goes between them.",
  "    function ensureAsk() {",
  "      var ask = page.querySelector('[data-role=ask]');",
  "      if (ask) return ask;",
  "      ask = el('div', 'st-ask-body');",
  "      ask.setAttribute('data-role', 'ask');",
  "      created.push(ask);",
  "      var label = page.querySelector('.st-ask-label');",
  "      var box = page.querySelector('.st-ask');",
  "      moveTo(ask, label, null);",
  "      moveTo(ask, box, null);",
  "      return ask;",
  "    }",
  "",
  "    for (var h = 0; h < order.length; h += 1) {",
  "      var id = order[h];",
  "      if (id === 'agent') continue;",
  "      attachHosts(frames[id], hostsFor(id));",
  "    }",
  "    var agentHosts = listOf(hooks.hosts ? hooks.hosts.agent : null);",
  "    if (agentHosts.length === 0) agentHosts = [ensureAsk()];",
  "    attachHosts(frames.agent, agentHosts);",
  "",
  "    // History brings the side panel's own head and note into its frame",
  "    // header. What is left of the aside is then empty and hidden.",
  "    var sideHead = page.querySelector('.st-side-head');",
  "    var sideNote = page.querySelector('.st-side-note');",
  "    if (sideHead) moveTo(frames.history.head, sideHead, sideNote);",
  "    if (sideNote) moveTo(frames.history.head, sideNote, null);",
  "    var aside = page.querySelector('.st-side');",
  "    var asideWasHidden = aside ? isHidden(aside) : false;",
  "    if (aside && aside.children.length === 0) setHidden(aside, true);",
  "",
  "    // ---- notes and the unread dot ----------------------------------------",
  "",
  "    function updateNotes() {",
  "      for (var id in frames) {",
  "        if (!hasOwn(frames, id)) continue;",
  "        var entry = frames[id];",
  "        if (!entry.note) continue;",
  "        var visible = false;",
  "        for (var i = 0; i < entry.hosts.length; i += 1) {",
  "          if (!isHidden(entry.hosts[i])) visible = true;",
  "        }",
  "        setHidden(entry.note, visible);",
  "      }",
  "    }",
  "",
  "    function setUnread(value) {",
  "      var want = value === true;",
  "      if (state.unread === want) return;",
  "      state.unread = want;",
  "      if (frames.agent && frames.agent.dot) setHidden(frames.agent.dot, !want);",
  "    }",
  "",
  "    function isShown(id) {",
  "      if (!state.shown || state.shown[id] !== true) return false;",
  "      return state.screen === null || state.screen === 'session';",
  "    }",
  "",
  "    function observerCtor() {",
  "      if (typeof window.MutationObserver === 'function') return window.MutationObserver;",
  "      if (document.defaultView && typeof document.defaultView.MutationObserver === 'function') {",
  "        return document.defaultView.MutationObserver;",
  "      }",
  "      return null;",
  "    }",
  "",
  "    function watchHosts() {",
  "      var Observer = observerCtor();",
  "      if (!Observer) return;",
  "      for (var id in frames) {",
  "        if (!hasOwn(frames, id)) continue;",
  "        var entry = frames[id];",
  "        if (entry.hosts.length === 0) continue;",
  "        var hiddenObserver = new Observer(function () { updateNotes(); });",
  "        for (var i = 0; i < entry.hosts.length; i += 1) {",
  "          hiddenObserver.observe(entry.hosts[i], { attributes: true, attributeFilter: ['hidden'] });",
  "        }",
  "        observers.push(hiddenObserver);",
  "      }",
  "      var agent = frames.agent;",
  "      if (!agent || agent.hosts.length === 0) return;",
  "      var logObserver = new Observer(function () {",
  "        if (closed) return;",
  "        if (!isShown('agent')) setUnread(true);",
  "      });",
  "      for (var j = 0; j < agent.hosts.length; j += 1) {",
  "        logObserver.observe(agent.hosts[j], { childList: true, subtree: true });",
  "      }",
  "      observers.push(logObserver);",
  "    }",
  "",
  "    // ---- the width class --------------------------------------------------",
  "",
  "    function currentSizeClass() {",
  "      var width = window.innerWidth;",
  "      if (typeof width === 'number' && isFinite(width)) return layoutApi.sizeClassFor(width);",
  "      if (mediaLarge && mediaLarge.matches) return 'laptop';",
  "      if (mediaMedium && mediaMedium.matches) return 'tablet';",
  "      return 'phone';",
  "    }",
  "",
  "    function watchMedia() {",
  "      if (typeof window.matchMedia !== 'function') return;",
  "      try {",
  "        mediaMedium = window.matchMedia('(min-width: 640px)');",
  "        mediaLarge = window.matchMedia('(min-width: 1024px)');",
  "      } catch (err) {",
  "        mediaMedium = null;",
  "        mediaLarge = null;",
  "        return;",
  "      }",
  "      var queries = [mediaMedium, mediaLarge];",
  "      for (var i = 0; i < queries.length; i += 1) {",
  "        var query = queries[i];",
  "        if (!query) continue;",
  "        var handler = function () { refresh(); };",
  "        if (typeof query.addEventListener === 'function') query.addEventListener('change', handler);",
  "        else if (typeof query.addListener === 'function') query.addListener(handler);",
  "        media.push({ query: query, handler: handler });",
  "      }",
  "    }",
  "",
  "    // ---- applying a layout ------------------------------------------------",
  "",
  "    function readScreen() {",
  "      var value = 'session';",
  "      if (typeof hooks.screen === 'function') {",
  "        try { value = hooks.screen(); } catch (err) { value = 'session'; }",
  "      }",
  "      return value === 'arrangement' || value === 'mixer' ? value : 'session';",
  "    }",
  "",
  "    function applyLayout(layout, sizeClass) {",
  "      var rows = layout && Array.isArray(layout.shown) ? layout.shown : [];",
  "      var shown = {};",
  "      var desired = [];",
  "      var i;",
  "      for (i = 0; i < rows.length; i += 1) {",
  "        var row = rows[i];",
  "        var entry = frames[row.id];",
  "        if (!entry) continue;",
  "        shown[row.id] = true;",
  "        setAttr(entry.frame, 'data-size', row.size);",
  "        setStyle(entry.frame, '--st-span', String(layoutApi.columnSpan(row.size, sizeClass)));",
  "        desired.push(entry.frame);",
  "      }",
  "      placeNodes(widgets, desired);",
  "      var trayNodes = [];",
  "      var tableOrder = layoutApi.WIDGET_ORDER || WIDGET_ORDER;",
  "      for (i = 0; i < tableOrder.length; i += 1) {",
  "        var trayId = tableOrder[i];",
  "        if (shown[trayId]) continue;",
  "        if (frames[trayId]) trayNodes.push(frames[trayId].frame);",
  "      }",
  "      placeNodes(tray, trayNodes);",
  "      return shown;",
  "    }",
  "",
  "    // ---- the one refresh --------------------------------------------------",
  "",
  "    function refresh() {",
  "      if (closed) return;",
  "      var sizeClass = currentSizeClass();",
  "      var layout = layoutApi.loadLayout(storage, songId, state.mode, sizeClass);",
  "      var text = layoutApi.serializeLayout(layout);",
  "      var screen = readScreen();",
  "      var layoutChanged = text !== state.layoutText;",
  "      var shown = layoutChanged ? applyLayout(layout, sizeClass) : (state.shown || {});",
  "      for (var i = 0; i < modeButtons.length; i += 1) {",
  "        setAttr(modeButtons[i].node, 'aria-pressed', modeButtons[i].mode === state.mode ? 'true' : 'false');",
  "      }",
  "      setHidden(widgets, screen !== 'session');",
  "      setAttr(screenBox, 'data-screen', screen);",
  "      updateNotes();",
  "      if (shown.agent === true && screen === 'session') setUnread(false);",
  "      var newlyShown = false;",
  "      if (layoutChanged && state.shown) {",
  "        for (var id in shown) {",
  "          if (hasOwn(shown, id) && state.shown[id] !== true) newlyShown = true;",
  "        }",
  "      }",
  "      state.layoutText = text;",
  "      state.shown = shown;",
  "      state.screen = screen;",
  "      if (newlyShown && !state.inRender && typeof hooks.render === 'function') {",
  "        state.inRender = true;",
  "        try { hooks.render(); } catch (err) { /* the page draws again next render */ }",
  "        state.inRender = false;",
  "      }",
  "    }",
  "",
  "    function setMode(next) {",
  "      if (closed) return;",
  "      var mode = MODES.indexOf(next) >= 0 ? next : 'compose';",
  "      var changed = state.mode !== mode;",
  "      state.mode = mode;",
  "      writeValue(storage, MODE_KEY, mode);",
  "      refresh();",
  "      if (changed && typeof hooks.onMode === 'function') {",
  "        try { hooks.onMode(mode); } catch (err) { /* the page keeps its own mode */ }",
  "      }",
  "    }",
  "",
  "    function destroy() {",
  "      if (closed) return;",
  "      closed = true;",
  "      for (var i = 0; i < observers.length; i += 1) {",
  "        try { observers[i].disconnect(); } catch (err) { /* gone */ }",
  "      }",
  "      observers = [];",
  "      for (i = 0; i < media.length; i += 1) {",
  "        var entry = media[i];",
  "        try {",
  "          if (typeof entry.query.removeEventListener === 'function') entry.query.removeEventListener('change', entry.handler);",
  "          else if (typeof entry.query.removeListener === 'function') entry.query.removeListener(entry.handler);",
  "        } catch (err) { /* gone */ }",
  "      }",
  "      media = [];",
  "      for (i = 0; i < listeners.length; i += 1) {",
  "        try { listeners[i].node.removeEventListener(listeners[i].type, listeners[i].handler); } catch (err) { /* gone */ }",
  "      }",
  "      listeners = [];",
  "      for (i = moved.length - 1; i >= 0; i -= 1) {",
  "        var move = moved[i];",
  "        if (!move.parent) continue;",
  "        try {",
  "          var before = move.next && move.next.parentNode === move.parent ? move.next : null;",
  "          move.parent.insertBefore(move.node, before);",
  "        } catch (err) { /* the page is going away */ }",
  "      }",
  "      moved = [];",
  "      for (i = created.length - 1; i >= 0; i -= 1) {",
  "        var node = created[i];",
  "        if (node && node.parentNode) node.parentNode.removeChild(node);",
  "      }",
  "      created = [];",
  "      if (aside && isHidden(aside) !== asideWasHidden) setHidden(aside, asideWasHidden);",
  "      if (page.__studioShell === control) page.__studioShell = null;",
  "    }",
  "",
  "    control.refresh = refresh;",
  "    control.setMode = setMode;",
  "    control.destroy = destroy;",
  "    control.topBar = function () { return top; };",
  "    control.layoutEntries = function () { return entries; };",
  "    control.layoutMidi = function () { return midiEntries; };",
  "    page.__studioShell = control;",
  "    watchMedia();",
  "    watchHosts();",
  "    refresh();",
  "    return control;",
  "  }",
  "})();",
].join("\n");

/**
 * The shell's styles.
 *
 * The top bar sticks to the top of the page (it is not a fixed layer, so it
 * never covers the player bar), the frames share a twelve, six or one column
 * row and take their span from `--st-span`, which `columnSpan` wrote. Every
 * new control is at least 44 px and a press is a press, never a text
 * selection. The rules belong after the page's own style block.
 *
 * @type {string}
 */
export const SHELL_CSS = [
  '/* The one top bar: the back link, the title, the modes and the layout menu. */',
  '.studio .st-top {',
  '  position: sticky; top: 0; z-index: 1040;',
  '  display: flex; flex-wrap: wrap; align-items: center; gap: 8px;',
  '  padding: 6px 12px; background: var(--st-head, #1B1E22);',
  '  border-bottom: 1px solid var(--st-line, #2C3036);',
  '  font-family: Inter, system-ui, sans-serif;',
  '  user-select: none; -webkit-user-select: none; -webkit-touch-callout: none;',
  '}',
  '.studio .st-top .st-title { font-weight: 600; }',
  '.studio .st-top .st-back,',
  '.studio .st-top .st-title { flex: 0 0 auto; }',
  '/* Every control the shell adds is a 44 px target. */',
  '.studio .st-top button,',
  '.studio .st-top [role=button] { min-width: 44px; min-height: 44px; }',
  '.studio .st-mode-switch { display: flex; gap: 4px; }',
  '.studio .st-mode-switch-btn {',
  '  padding: 0 12px; border: 1px solid var(--st-line, #2C3036); border-radius: 8px;',
  '  background: transparent; color: var(--st-text, #E9E6DF);',
  '  font: inherit; font-size: 13px; cursor: pointer;',
  '  user-select: none; -webkit-user-select: none; -webkit-touch-callout: none;',
  '}',
  '.studio .st-mode-switch-btn[aria-pressed=true] {',
  '  background: var(--st-accent, #E8A33D); border-color: var(--st-accent, #E8A33D);',
  '  color: #1B1E22;',
  '}',
  '.studio .st-top .st-modes { display: flex; flex-wrap: wrap; gap: 4px; }',
  '.studio .st-layout-menu { position: relative; margin-left: auto; }',
  '.studio .st-layout-pop {',
  '  position: absolute; right: 0; top: calc(100% + 6px);',
  '  min-width: 240px; overflow: auto; z-index: 1;',
  '  max-height: min(70vh, calc(100vh - var(--crow-player-h, 0px) - var(--shell-tabs-h, 0px) - 96px));',
  '  padding: 8px; border: 1px solid var(--st-line, #2C3036); border-radius: 10px;',
  '  background: var(--st-panel, #20242A); box-shadow: 0 12px 32px rgba(0, 0, 0, 0.4);',
  '  user-select: none; -webkit-user-select: none; -webkit-touch-callout: none;',
  '}',
  '.studio .st-layout-pop[hidden] { display: none; }',
  '.studio .st-layout-pop button {',
  '  width: 100%; justify-content: flex-start; text-align: left;',
  '  min-width: 44px; min-height: 44px;',
  '}',
  '.studio .st-layout-entries,',
  '.studio .st-layout-midi { display: flex; flex-direction: column; gap: 4px; }',
  '.studio .st-layout-midi:empty { display: none; }',
  '/* The timeline and the mixer are the screens; the widgets sit beside them. */',
  '.studio .st-screen { min-width: 0; }',
  '.studio .st-widgets {',
  '  display: grid; grid-template-columns: repeat(12, minmax(0, 1fr));',
  '  gap: 12px; min-width: 0;',
  '}',
  '.studio .st-widgets[hidden] { display: none; }',
  '.studio .st-widget {',
  '  display: flex; flex-direction: column; min-width: 0;',
  '  grid-column: span var(--st-span, 12);',
  '  background: var(--st-panel, #20242A); border: 1px solid var(--st-line, #2C3036);',
  '  border-radius: 10px; overflow: hidden;',
  '}',
  '.studio .st-widget-head {',
  '  display: flex; align-items: center; flex-wrap: wrap; gap: 8px;',
  '  min-height: 44px; padding: 0 12px;',
  '  border-bottom: 1px solid var(--st-line, #2C3036);',
  '  font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.06em;',
  '  color: var(--st-muted, #A9A59C);',
  '  user-select: none; -webkit-user-select: none; -webkit-touch-callout: none;',
  '}',
  '.studio .st-widget-body {',
  '  display: flex; flex-direction: column; flex: 1 1 auto;',
  '  min-width: 0; min-height: 0;',
  '}',
  '.studio .st-widget-note {',
  '  margin: 12px; color: var(--st-muted, #A9A59C); font-size: 13px;',
  '}',
  '.studio .st-widget-note[hidden] { display: none; }',
  '.studio .st-widget-dot {',
  '  width: 8px; height: 8px; margin-left: auto; border-radius: 50%;',
  '  background: var(--st-accent, #E8A33D);',
  '}',
  '.studio .st-widget-dot[hidden] { display: none; }',
  '.studio .st-widget-tray[hidden] { display: none; }',
  '/* A tablet is six columns; a phone is one widget per row. */',
  '@media (min-width: 640px) and (max-width: 1023px) {',
  '  .studio .st-widgets { grid-template-columns: repeat(6, minmax(0, 1fr)); }',
  '}',
  '@media (max-width: 639px) {',
  '  .studio .st-widgets { grid-template-columns: minmax(0, 1fr); }',
  '  .studio .st-widget { grid-column: span 1; }',
  '  .studio .st-top { gap: 6px; padding: 6px 8px; }',
  '  .studio .st-layout-menu { margin-left: 0; }',
  '}',
].join("\n");

/**
 * The shell's pure helpers, evaluated from the very string the page inlines.
 *
 * `new Function` with a `window` parameter means the script's one global lands
 * on the object this module keeps, and never on Node's `globalThis`.
 */
const shellApi = new Function("window", `${SHELL_SCRIPT}\nreturn window.StudioShell;`)({});

/**
 * The header text of one widget.
 * @param {string} id
 * @returns {string}
 */
export function widgetName(id) {
  return shellApi.widgetName(id);
}

/**
 * The sentence a widget frame shows when every host it wraps is hidden.
 * @param {string} id
 * @returns {string} the note, or an empty string for a widget with none
 */
export function emptyNote(id) {
  return shellApi.emptyNote(id);
}